values.content:
Write API changelog notifications.

API: {{ $json.apiName }}
Version: {{ $json.version || 'not specified' }}
Release date: {{ $json.releaseDate }}
Total changes: {{ $json.changeCount }}
Has breaking changes: {{ $json.hasBreaking }}
Has security changes: {{ $json.hasSecurity }}
Migration guide: {{ $json.migrationGuideUrl || 'not available' }}
Docs: {{ $json.docsUrl || 'not available' }}
Support: {{ $json.supportEmail || 'not specified' }}

Changes:
{{ $json.changes.map(c=>c.id+' ['+c.type+']['+c.severity+']'+(c.endpoint?' '+c.endpoint:'')+(c.field?' field:'+c.field:'')+': '+c.description+(c.migrationSteps?' | Migration: '+c.migrationSteps:'')+(c.deprecationDate?' | Deprecated by: '+c.deprecationDate:'')+(c.replacedBy?' | Replaced by: '+c.replacedBy:'')).join('\n') }}

Return JSON:
{"email_notification":{"subject":"","plain_text_summary":"2-3 sentences: what changed in plain English, what developers need to do","sections":[{"section_type":"breaking_changes|deprecations|new_features|improvements|bug_fixes|security","headline":"","items":[{"change_id":"","title":"","description":"clear technical description","impact":"what breaks or changes for developers","migration":"specific steps — what to change in code","example_before":"","example_after":"","timeline":"when this must be done by"}]}]},"slack_message":{"text":"","blocks_summary":"a concise Slack-friendly summary under 200 chars"},"action_required":true,"action_deadline":"if breaking or deprecated, by when","affected_developer_count_estimate":"who needs to act on this"}
